SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, merchant, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, PERCENTILE_APPROX(amount, 0.95) AS amount_p95, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, MAX(txn_time) AS last_txn_time, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, SUM(amount) AS total_amount FROM transactions GROUP BY DATE_TRUNC('MONTH', txn_time), merchant, DATE_TRUNC('QUARTER', txn_time) ORDER BY num_txn_types DESC;
